from pathlib import Path

path = Path("core-upstream/native/quic/mobilebridge/vpn_tunnel.go")
source = path.read_text(encoding="utf-8")
old = "\tdefer upstream.Close()\n\tdone := make(chan struct{})\n\tgo func() {\n\t\t_, _ = io.Copy(countedWriter{upstream, &h.metricsOrCurrent().up}, conn)\n\t\tif cw, ok := upstream.(interface{ CloseWrite() error }); ok {\n\t\t\t_ = cw.CloseWrite()\n\t\t}\n\t\tclose(done)\n\t}()\n\t_, _ = io.Copy(countedWriter{conn, &h.metricsOrCurrent().down}, upstream)\n\t_ = conn.Close()\n\t<-done"
new = "\th.relayTCP(conn, upstream)\n}\n\n// relayTCP preserves a healthy stream, but interrupts both directions when\n// either copy fails or the tunnel stops. No idle or response-duration limit.\nfunc (h *vpnFlowHandler) relayTCP(conn net.Conn, upstream io.ReadWriteCloser) {\n\tmetrics := h.metricsOrCurrent()\n\tvar once sync.Once\n\tabort := func() {\n\t\tonce.Do(func() {\n\t\t\t_ = conn.Close()\n\t\t\t// QUIC stream Close may only close the send half. A deadline\n\t\t\t// also wakes any blocked receiver on transports supporting it.\n\t\t\tif d, ok := upstream.(interface{ SetDeadline(time.Time) error }); ok {\n\t\t\t\t_ = d.SetDeadline(time.Now())\n\t\t\t}\n\t\t\t_ = upstream.Close()\n\t\t})\n\t}\n\tdefer abort()\n\tparent := h.ctx\n\tif parent == nil {\n\t\tparent = context.Background()\n\t}\n\tstop := context.AfterFunc(parent, abort)\n\tdefer stop()\n\tdone := make(chan struct{})\n\tgo func() {\n\t\tdefer close(done)\n\t\tif _, err := io.Copy(countedWriter{upstream, &metrics.up}, conn); err != nil {\n\t\t\tif parent.Err() == nil && !errors.Is(err, net.ErrClosed) {\n\t\t\t\th.recordError(\"TCP 上行\", err)\n\t\t\t}\n\t\t\tabort()\n\t\t\treturn\n\t\t}\n\t\tif cw, ok := upstream.(interface{ CloseWrite() error }); ok {\n\t\t\tif err := cw.CloseWrite(); err != nil {\n\t\t\t\tif parent.Err() == nil && !errors.Is(err, net.ErrClosed) {\n\t\t\t\t\th.recordError(\"TCP 上行结束\", err)\n\t\t\t\t}\n\t\t\t\tabort()\n\t\t\t}\n\t\t}\n\t}()\n\tif _, err := io.Copy(countedWriter{conn, &metrics.down}, upstream); err != nil {\n\t\tif parent.Err() == nil && !errors.Is(err, net.ErrClosed) {\n\t\t\th.recordError(\"TCP 下行\", err)\n\t\t}\n\t}\n\tabort()\n\t<-done"
if source.count(old) != 1:
    raise SystemExit("Pinned TCP relay mismatch")
path.write_text(source.replace(old, new, 1), encoding="utf-8")
path.with_name("vpn_relay_test.go").write_text("package mobilebridge\n\nimport (\n \"context\"\n \"io\"\n \"net\"\n \"testing\"\n \"time\"\n)\n\nfunc TestRelayDelayedChunksAndCancellation(t *testing.T) {\n ctx, cancel := context.WithCancel(context.Background())\n defer cancel()\n client, local := net.Pipe()\n remote, server := net.Pipe()\n defer client.Close()\n defer local.Close()\n defer remote.Close()\n defer server.Close()\n _ = client.SetDeadline(time.Now().Add(3*time.Second))\n _ = server.SetDeadline(time.Now().Add(3*time.Second))\n h := &vpnFlowHandler{ctx:ctx, metrics:resetTunnelDiagnostics()}\n done := make(chan struct{})\n go func(){ defer close(done); h.relayTCP(local, remote) }()\n for _, chunk := range []string{\"first\", \"second\", \"third\"} {\n  result := make(chan error,1)\n  go func(s string){ _,err:=server.Write([]byte(s)); result<-err }(chunk)\n  b:=make([]byte,len(chunk))\n  if _,err:=io.ReadFull(client,b);err!=nil || string(b)!=chunk {t.Fatalf(\"stream chunk %q: %v\",b,err)}\n  if err:=<-result;err!=nil {t.Fatal(err)}\n  time.Sleep(20*time.Millisecond)\n }\n if h.metrics.down.Load()!=16 { t.Fatalf(\"incorrect download count: %d\",h.metrics.down.Load()) }\n cancel()\n select { case <-done: case <-time.After(2*time.Second):t.Fatal(\"relay did not stop after tunnel cancellation\") }\n}\n", encoding="utf-8")
print("TCP relay error reporting and cancellation regression test installed")
